<?php require __DIR__ . '/bootstrap.php'; auth_required(); ?><!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/treevolution-v6-3.css"><title>Add story | Treevolution</title></head><body class="admin"><main class="container formcard"><p style="float:right"><a href="logout.php">Sign out</a></p><h1>Add a Treevolution update</h1><p>Upload one current project image and a short factual story. The image is resized and converted to WebP before being committed to GitHub. A successful commit automatically starts the test-site deployment workflow.</p><form action="submit.php" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label for="title">Story title</label><input id="title" name="title" maxlength="90" required placeholder="e.g. Beech reduction in Lewes"><label for="date">Date</label><input id="date" type="date" name="date" value="<?=date('Y-m-d')?>" required><label for="category">Category</label><select id="category" name="category"><option>Tree removal</option><option>Tree reduction</option><option>Pollarding</option><option>Hedge cutting</option><option>Stump removal</option><option>Other tree care</option></select><label for="body">Story</label><textarea id="body" name="body" maxlength="1200" required placeholder="What was the job, roughly where was it, and what was achieved?"></textarea><label for="image">Image (JPG, PNG or WebP; max 8MB)</label><input id="image" type="file" name="image" accept="image/jpeg,image/png,image/webp" required><div class="upload-preview" id="uploadPreview" hidden><strong>Image orientation preview</strong><p class="orientation-warning">Check that the photograph is upright exactly as you want it displayed on the website.</p><img id="previewImage" alt="Preview of selected upload"></div><label class="orientation-check"><input type="checkbox" name="orientation_confirmed" value="1" required> <span>I confirm this photograph is upright and correctly orientated.</span></label><label for="alt">Image description for accessibility</label><input id="alt" name="alt" maxlength="160" required placeholder="e.g. Completed beech tree reduction in a Lewes garden"><p><button class="btn btn-primary" type="submit">Publish update</button></p></form></main><script>
const input=document.getElementById('image'), box=document.getElementById('uploadPreview'), preview=document.getElementById('previewImage');
if(input&&box&&preview){input.addEventListener('change',()=>{const f=input.files&&input.files[0];if(!f){box.hidden=true;preview.removeAttribute('src');return;}preview.src=URL.createObjectURL(f);box.hidden=false;});}
</script></body></html>
